			});
		var validatorsSideEffects = validators
			.map(function (validator) {
				return {
					name: validator.name,
					link: validator.link,
					count: validator.sideEffects.length,
					sideEffects: validator.sideEffects
				};
			})
			.filter(function (o) {
				return o.count !== 0;
			})
			.sort(function (a, b) {
				return a.count - b.count;
			});
